"""Writes the per-install bits of the Chrome extension (server URL + secret token, icon)."""
from __future__ import annotations

import json
import socket
import threading
import time
from pathlib import Path

from PIL import Image, ImageDraw

from . import config, extjobs

EXT_DIR = config.ROOT / "extension"


def write(cfg: config.Config | None = None) -> Path:
    cfg = cfg or config.load()
    conf = {"server": f"http://127.0.0.1:{cfg.web.port}", "token": extjobs.token(cfg)}
    (EXT_DIR / "config.js").write_text(
        "// Generated by `pto extension`. Contains the secret token: don't share this file.\n"
        f"export const CONFIG = {json.dumps(conf)};\n", encoding="utf-8")
    icon = EXT_DIR / "icon.png"
    if not icon.exists():
        im = Image.new("RGBA", (128, 128), (0, 0, 0, 0))
        d = ImageDraw.Draw(im)
        d.rounded_rectangle((8, 8, 120, 120), radius=28, fill=(47, 111, 222, 255))
        d.polygon([(64, 30), (96, 66), (76, 66), (76, 98), (52, 98), (52, 66), (32, 66)], fill=(255, 255, 255, 255))
        im.save(icon)
    return EXT_DIR


def configured(cfg: config.Config | None = None) -> bool:
    p = EXT_DIR / "config.js"
    return p.exists() and extjobs.token(cfg) in p.read_text(encoding="utf-8")


def server_running(cfg: config.Config) -> bool:
    with socket.socket() as s:
        s.settimeout(1)
        return s.connect_ex(("127.0.0.1", cfg.web.port)) == 0


def ensure_server(cfg: config.Config) -> bool:
    """CLI commands that hand work to the extension need the API up. Start it in-process if `pto serve` isn't running.
    Returns True if we started it."""
    if server_running(cfg):
        return False
    import uvicorn

    from .web.app import app

    server = uvicorn.Server(uvicorn.Config(app, host=cfg.web.host, port=cfg.web.port, log_level="warning"))
    threading.Thread(target=server.run, daemon=True, name="api").start()
    for _ in range(40):
        if server_running(cfg):
            return True
        time.sleep(0.25)
    raise RuntimeError(f"could not start the API on port {cfg.web.port}")
